// Extract Payload v5.3
// persona มาจาก Vercel (User + ethical_profiles + memory_facts + relevant_memories)
// ไม่ต้อง query DB ใน WF2 อีกต่อไป
const raw = $input.first().json.body || $input.first().json;

// Parse persona (อาจเป็น string หรือ object)
let persona = {};
try {
  const p = raw.persona;
  persona = typeof p === 'string' ? JSON.parse(p) : (p || {});
} catch(e) {
  persona = {};
}

// Ensure persona มี defaults ที่จำเป็น
const userId = raw.userId || persona.userId || '';
persona.userId = userId;
persona.language_preference = persona.language_preference || 'th';
persona.tokens = persona.tokens || {};
persona.relevant_memories = persona.relevant_memories || [];
persona.key_facts = persona.key_facts || [];
persona.interests = persona.interests || [];
persona.ethical_profile = persona.ethical_profile || null;

console.log(`[WF2 Extract] userId=${userId.substring(0,8)}... | lang=${persona.language_preference} | memories=${persona.relevant_memories.length} | facts=${persona.key_facts.length}`);

return {
  json: {
    userId,
    sessionId:       raw.sessionId,
    source:          raw.source || 'chat',
    message:         raw.message || '',
    originalMessage: raw.originalMessage || raw.message || '',
    timestamp:       raw.timestamp || new Date().toISOString(),
    replyTarget:     raw.replyTarget,
    replyToken:      raw.replyToken,
    databaseUrl:     raw.databaseUrl || '',
    persona,
    rawPayload:      raw
  }
};

// Prepare JARVIS v5.5
// ─────────────────────────────────────────────────────────────
// FIX: ไม่ใช้ n8n credential เลย
// Authorization header สร้างจาก $env.OPENROUTER_API_KEY หรือ user token
// ─────────────────────────────────────────────────────────────
const payload  = $input.first().json;
const message  = payload.message || '';
const persona  = payload.persona || {};
const lang     = persona.language_preference || 'th';
const name_    = persona.name || 'User';
const tier     = persona.subscriptionTier || 'FREE';
const stage    = persona.ethical_profile?.growth_stage || 2;
const stageLabel = persona.ethical_profile?.growth_stage_label || 'Developing';
const interests  = (persona.interests || []).slice(0, 5).join(', ') || 'not specified';
const keyFacts   = (persona.key_facts || []).slice(0, 3).join(' | ') || 'none';
const recentMemTypes = (persona.relevant_memories || []).map(m => m.type).join(', ') || 'none';

// ── API Key: user key → system key ───────────────────────────
const userKey   = persona.tokens?.openrouter_access_token || '';
const systemKey = $env.OPENROUTER_API_KEY || '';
const apiKey    = userKey || systemKey || '';

const PAID_MODEL = 'anthropic/claude-haiku-4-5';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';
const model    = userKey ? PAID_MODEL : FREE_MODEL;
const keyType  = userKey ? 'user' : (systemKey ? 'system' : 'none');
const hasAuth  = apiKey.length > 0;

// ── Agent URLs ────────────────────────────────────────────────
const n8nBase = $env.N8N_BASE_URL || 'http://localhost:5678';
const AGENT_URLS = {
  wf3a: $env.N8N_WF3A_URL || `${n8nBase}/webhook/wf3a-secretary`,
  wf3b: $env.N8N_WF3B_URL || `${n8nBase}/webhook/wf3b-soul`,
  wf3c: $env.N8N_WF3C_URL || `${n8nBase}/webhook/wf3c-careercoach`,
  wf3d: $env.N8N_WF3D_URL || `${n8nBase}/webhook/wf3d-explorer`,
  wf3e: $env.N8N_WF3E_URL || `${n8nBase}/webhook/wf3e-creator`,
  wf3f: $env.N8N_WF3F_URL || `${n8nBase}/webhook/wf3f-homemate`,
  wf3g: $env.N8N_WF3G_URL || `${n8nBase}/webhook/wf3g-healthcoach`
};

const SYSTEM_PROMPT = `You are JARVIS — the central cognitive router of an advanced personal AI system.
Your function: Decompose the user's message into a structured dispatch plan.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
AGENT REGISTRY
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

wf3a [SECRETARY] — External coordination & communication
  • Calendar, reminders, alarms, countdowns, scheduling
  • Email, LINE notify, Telegram, Discord, Slack, SMS
  • Social media: post, DM, tweet, LinkedIn
  • Task management: todo, checklist, Notion, Trello

wf3b [SOUL] — Inner world, emotions & personal growth
  • Emotional processing: venting, sharing feelings, being heard
  • Journaling: daily log, gratitude, mood entry, reflection
  • Personal growth: habits, streaks, mindfulness, meditation
  • Relationships: emotional angle
  • Crisis: hopelessness, self-harm → ALWAYS wf3b, ALWAYS crisis=true

wf3c [CAREER COACH] — Finance, work & professional
  • Personal finance: budget, expenses, savings
  • Investment: stocks, crypto, funds
  • Career: job search, resume, interview

wf3d [EXPLORER] — Knowledge & real-world data
  • Web search: news, research, facts
  • Real-time: weather, exchange rates
  • Location: maps, travel info

wf3e [CREATOR] — Content generation
  • AI image, TTS, creative writing, translation

wf3f [HOME MATE] — Ambient & entertainment
  • Music: Spotify, Sonos
  • Smart home: Home Assistant

wf3g [HEALTH COACH] — Physical health
  • Nutrition: calorie, meal logging
  • Fitness: workout, exercise log

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
- Single intent → 1 item
- Multi intent → max 3 items, ordered by priority
- crisis → wf3b always
- gating=true for emotional depth
- Output ONLY valid JSON, no markdown

{
  "intents": [
    {
      "agent": "wf3x",
      "priority": 1,
      "sub_task": "focused instruction in user language",
      "gating": false,
      "crisis": false
    }
  ]
}

CONTEXT:
User: ${name_} | Language: ${lang} | Tier: ${tier}
Growth: ${stage}/5 (${stageLabel})
Interests: ${interests}
Key facts: ${keyFacts}
Recent memory themes: ${recentMemTypes}`;

const openrouterBody = {
  model,
  max_tokens: 300,
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: message }
  ]
};

console.log(`[JARVIS v5.5] keyType=${keyType} | hasAuth=${hasAuth} | model=${model}`);

return {
  json: {
    ...payload,
    _jarvis: {
      apiKey,
      authHeader: hasAuth ? `Bearer ${apiKey}` : '',
      model,
      keyType,
      hasAuth,
      openrouterBody,
      AGENT_URLS,
      n8nBase
    }
  }
};

// Keyword Fallback v5.5
// ใช้เมื่อไม่มี OpenRouter API key
// Parse & Route รับ _openrouter_skipped=true และใช้ keyword routing แทน
const payload = $input.first().json;
console.log('[JARVIS Fallback] No API key — keyword routing');
return {
  json: {
    ...payload,
    choices: null,
    _openrouter_skipped: true
  }
};

// Parse & Route v5.4
// ─────────────────────────────────────────────────────────────
// input: HTTP Request response (choices[]) หรือ error
// context: ดึงจาก node "Prepare JARVIS" ผ่าน $('Prepare JARVIS').item
// ─────────────────────────────────────────────────────────────
const httpResult = $input.first().json;

// ดึง original payload + jarvis config จาก Prepare JARVIS node
const prepareNode = $('Prepare JARVIS').item;
const origPayload = prepareNode.json;
const jarvis      = origPayload._jarvis || {};
const AGENT_URLS  = jarvis.AGENT_URLS || {};
const n8nBase     = jarvis.n8nBase || 'http://localhost:5678';
const message     = origPayload.message || '';
const persona     = origPayload.persona || {};
const lang        = persona.language_preference || 'th';
const usedModel   = jarvis.model || null;

// ── Parse OpenRouter response ─────────────────────────────
const choices = httpResult.choices || null;
const rawText = choices?.[0]?.message?.content || null;

// ── Intent Parser ─────────────────────────────────────────
function parseIntents(text) {
  const VALID = ['wf3a','wf3b','wf3c','wf3d','wf3e','wf3f','wf3g'];
  try {
    if (!text) throw new Error('no text');
    const clean = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);
    const intents = parsed.intents || parsed;
    const arr = Array.isArray(intents) ? intents : [intents];
    const validated = arr
      .filter(i => i && VALID.includes(i.agent))
      .map(i => ({
        agent: i.agent,
        priority: [1,2,3].includes(i.priority) ? i.priority : 1,
        sub_task: i.sub_task || message,
        gating: i.gating === true,
        crisis: i.crisis === true
      }))
      .sort((a, b) => a.priority - b.priority)
      .slice(0, 3);
    const seen = new Set();
    const deduped = validated.filter(i => {
      if (seen.has(i.agent)) return false;
      seen.add(i.agent); return true;
    });
    if (deduped.length === 0) throw new Error('no valid intents');
    return deduped;
  } catch(e) {
    return [keywordRoute(message, lang)];
  }
}

function keywordRoute(msg, lang) {
  const t = msg.toLowerCase();
  if (/อยากตาย|ฆ่าตัว|สิ้นหวัง|want to die|hopeless/.test(t))
    return { agent: 'wf3b', priority: 1, sub_task: msg, gating: true, crisis: true };
  if (/นัด|ปฏิทิน|เตือน|ส่ง email|ส่งเมล|แจ้งเตือน/.test(t))
    return { agent: 'wf3a', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/หุ้น|กองทุน|งบ|เงิน|ลงทุน|resume|สัมภาษณ์/.test(t))
    return { agent: 'wf3c', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/ค้นหา|ค้น|ข่าว|สภาพอากาศ|แผนที่|search|weather/.test(t))
    return { agent: 'wf3d', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/รูปภาพ|สร้างรูป|แปล|image|translate|tts|เสียง/.test(t))
    return { agent: 'wf3e', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/เพลง|spotify|music|บ้าน|home assistant/.test(t))
    return { agent: 'wf3f', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/อาหาร|แคล|ออกกำลัง|สุขภาพ|nutrition|workout/.test(t))
    return { agent: 'wf3g', priority: 1, sub_task: msg, gating: false, crisis: false };
  return { agent: 'wf3b', priority: 1, sub_task: msg, gating: false, crisis: false };
}

const intents = parseIntents(rawText);
const primaryIntent = intents[0];
const hasCrisis = intents.some(i => i.crisis);
const hasGating = intents.some(i => i.gating || i.crisis);
const gatingIntents = intents.filter(i => i.gating || i.crisis);

console.log(`[Parse & Route v5.4] intents=${intents.map(i=>i.agent).join(',')} | model=${usedModel} | rawText=${!!rawText}`);

// Single foreground intent
const foregroundIntents = intents.filter(i => i.priority <= 2);
const intent = foregroundIntents[0] || intents[0];

return {
  json: {
    // Original payload fields (restored from Prepare JARVIS)
    userId:          origPayload.userId,
    sessionId:       origPayload.sessionId,
    source:          origPayload.source,
    originalMessage: message,
    message:         intent.sub_task,
    databaseUrl:     origPayload.databaseUrl,
    replyTarget:     origPayload.replyTarget,
    replyToken:      origPayload.replyToken,
    timestamp:       origPayload.timestamp,
    persona:         origPayload.persona,
    // Routing info
    targetAgent:     intent.agent,
    targetUrl:       AGENT_URLS[intent.agent],
    needsGating:     intent.gating,
    hasCrisis,
    _intents:        intents,
    _dispatch_mode:  'single',
    _router_model:   rawText ? usedModel : null,
    _router_version: 'v5.4',
    _gating_intents: hasGating ? gatingIntents : []
  }
};

// Format Response v5.3
// Normalize WF3x output → ส่งกลับ WF1 → Vercel
const raw = $input.first().json;

// ดึง message จาก WF3x response
const msg = raw.message || raw.response || raw.output || raw.agentOutput || raw.text
            || 'ขออภัย ไม่สามารถตอบได้ในขณะนี้ครับ';

console.log(`[WF2 Response] agent=${raw._primary_agent || raw.targetAgent} | msg_len=${String(msg).length}`);

return {
  json: {
    message:       msg,
    response:      msg,
    output:        msg,
    userId:        raw.userId,
    sessionId:     raw.sessionId,
    _primary_agent: raw._primary_agent || raw.targetAgent,
    _router_model:  raw._router_model,
    _router_version:'v5.3',
    _dispatch_mode: raw._dispatch_mode,
    hasCrisis:      raw.hasCrisis || false
  }
};
